// Sinh 100 dong hop le cho phep thu import hang loat
var rows = [];
for (var i = 1; i <= 100; i++) {
    rows.push({
        name: 'IMP-BULK-' + i + '-23127195',
        price: 1000 + i,
        description: 'bulk row ' + i,
        imageUrl: '',
        category_id: (i % 3) + 1
    });
}
pm.collectionVariables.set('bulkRows', JSON.stringify(rows));

