pm.test('inserted trong bao cao phai bang so ban ghi that su tang them', function (done) {
    var reported = Number(J().inserted);
    pm.sendRequest({
        url: pm.environment.get('baseUrl') + '/api/products',
        method: 'GET',
        header: { 'X-Student-Id': pm.environment.get('studentId') }
    }, function (err, res) {
        try {
        pm.expect(err).to.be.null;
        var before = Number(pm.collectionVariables.get('countBefore'));
        var actual = res.json().length - before;
        pm.expect(actual, 'bao cao noi inserted=' + reported + ' nhung CSDL tang ' + actual).to.eql(reported);
        done();
        } catch (e) { done(e); }
    });
});

